30	const PROCESSING_FEE = 5;
31	
32	/**
33	 * The spec keeps intermediate amounts as exact fractions and rounds only the
34	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
35	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
36	 *
37	 * So percentages are applied as integer rationals — multiply by the numerator
38	 * first, divide by the denominator last — and money is carried in hundredths
39	 * of a G. Both operands of every product stay integral, so no drift accrues.
40	 */
41	const SUBUNITS_PER_G = 100;
42	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
43	
44	/**
45	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
46	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
47	 * numerator. Modifiers are summed onto a base, never multiplied through it.
48	 */
49	interface Rate {
50	  num: number;
51	  den: number;
52	}
53	
54	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
55	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
56	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
57	
58	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
59	
60	/** An item is highly enchanted from this level upwards. */
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	/** A customer is long-standing from this many years of business upwards. */
64	const LOYALTY_YEARS = 2;
65	
66	/** The modifier amount `rate` contributes against `subunits` — not the total. */
67	const rateAmount = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
68	
69	/** Premiums round up — in the MHPCO's favour. */
70	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
71	
72	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
73	  sword: 100,
74	  amulet: 60,
75	  staff: 80,
76	  potion: 40,
77	  rune: 25,
78	  moonstone: 25,
79	};
80	
81	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
82	
83	const COMPONENT_TYPES = ["rune", "moonstone"];
84	
85	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
86	
87	/** Exactly this many alike components form a block, priced as one unit. */
88	const COMPONENT_BLOCK_SIZE = 3;
89	const COMPONENT_BLOCK_PREMIUM = 60;
90	
91	/** Splits items into those matching the predicate and those that do not. */
92	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
93	  items.filter(matches),
94	  items.filter((item) => !matches(item)),
95	];
96	
97	const groupByType = (items: Item[]): Map<string, Item[]> => {
98	  const groups = new Map<string, Item[]>();
99	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
100	
101	  return groups;
102	};
103	
104	const sumOfBasePremiums = (items: Item[]): number =>
105	  items.reduce((total, item) => total + basePremiumOf(item), 0);
106	
107	/**
108	 * Alike components — those of the very same type — form a block when there are
109	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
110	 * Any other count is priced per component.
111	 */
112	const componentGroupPremium = (group: Item[]): number =>
113	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
114	
115	/**
116	 * The policy base premium: every insured item's base premium, summed — except
117	 * that each group of alike components is priced as blocks where it can be.
118	 */
119	const policyBasePremiumOf = (items: Item[]): number => {
120	  const [components, mainItems] = partition(items, isComponent);
121	  const componentsTotal = [...groupByType(components).values()].reduce(
122	    (total, group) => total + componentGroupPremium(group),
123	    0,
124	  );
125	
126	  return sumOfBasePremiums(mainItems) + componentsTotal;
127	};
128	
129	/** The total the given rates contribute against a shared base. */
130	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
131	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
132	
133	const isHighlyEnchanted = (item: Item): boolean =>
134	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
135	
136	/** Which item-specific modifiers an item attracts, by its own attributes. */
137	const ratesForItem = (item: Item): Rate[] => [
138	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
139	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
140	];
141	
142	const isLongStanding = (customer: Customer): boolean =>
143	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
144	
145	/** Which policy-wide modifiers a policy attracts, by the customer's history. */
146	const ratesForPolicy = (customer: Customer): Rate[] => [
147	  FIRST_INSURANCE_SURCHARGE,
148	  ...(isLongStanding(customer) ? [LOYALTY_DISCOUNT] : []),
149	];
150	
151	/** Item-specific modifiers apply to the affected item's own base premium. */
152	const itemModifiersOf = (items: Item[]): number =>
153	  items.reduce(
154	    (total, item) =>
155	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
156	    0,
157	  );
158	
159	/**
160	 * Modifiers are additive amounts, each computed against its own base: item
161	 * modifiers against the affected item, policy-wide modifiers against the
162	 * policy base premium. The processing fee is added at the very end.
163	 */
164	const quotePremium = (items: Item[], customer: Customer): number => {
165	  const policyBase = toSubunits(policyBasePremiumOf(items));
166	
167	  return toPremiumGold(
168	    policyBase +
169	      itemModifiersOf(items) +
170	      sumOfRateAmounts(policyBase, ratesForPolicy(customer)) +
171	      toSubunits(PROCESSING_FEE),
172	  );
173	};
174	
175	export const runScenario = (scenario: Scenario): ScenarioResults => {
176	  return {
177	    results: scenario.steps.map((step) => ({
178	      premium: quotePremium(step.items, scenario.customer),
179	    })),
180	  };
181	};
